using System.Drawing;using System.Windows.Forms;
namespace LSE.AutoCADElectrical.ProjectDoctor;
public sealed class TextReportForm:Form{readonly TextBox box=new(){Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Dock=DockStyle.Fill,Font=new Font("Consolas",9.5f),BackColor=SystemColors.Window};
 public TextReportForm(string title,string text,bool wrap=false){Text=title;StartPosition=FormStartPosition.CenterParent;Size=new Size(1000,640);MinimumSize=new Size(600,400);if(wrap){box.WordWrap=true;box.ScrollBars=ScrollBars.Vertical;box.Font=new Font("Segoe UI",10f);}box.Text=text;var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4,RowCount=2,Padding=new Padding(10)};p.ColumnStyles.Add(new(SizeType.Percent,100));p.ColumnStyles.Add(new(SizeType.Absolute,100));p.ColumnStyles.Add(new(SizeType.Absolute,100));p.ColumnStyles.Add(new(SizeType.Absolute,100));p.RowStyles.Add(new(SizeType.Percent,100));p.RowStyles.Add(new(SizeType.Absolute,44));
  p.Controls.Add(box,0,0);p.SetColumnSpan(box,4);var save=new Button{Text="Save as...",Dock=DockStyle.Fill};save.Click+=(_,_)=>{using var d=new SaveFileDialog{Filter="Text (*.txt)|*.txt",FileName=wrap?"LSE_Doctor_Help.txt":"LSE_DoctorReport.txt"};if(d.ShowDialog(this)==DialogResult.OK)File.WriteAllText(d.FileName,box.Text);};
  var copy=new Button{Text="Copy",Dock=DockStyle.Fill};copy.Click+=(_,_)=>{try{Clipboard.SetText(box.Text.Length==0?" ":box.Text);}catch{}};var close=new Button{Text="Close",Dock=DockStyle.Fill};close.Click+=(_,_)=>Close();p.Controls.Add(save,1,1);p.Controls.Add(copy,2,1);p.Controls.Add(close,3,1);Controls.Add(p);CancelButton=close;Shown+=(_,_)=>{box.SelectionStart=0;box.SelectionLength=0;close.Focus();};}
}
